def extend(styles, families):
 import json, unicodedata
 from pathlib import Path
 from extra_styles import FAMILY_AUDIO
 from product_styles import AUDIO, LOCK
 from property_styles import PROPERTY_LOCK
 from software_styles import SOFTWARE_LOCK
 from presentation_styles import PRESENTATION_RULE
 from avatar_styles import RULE
 refs=json.loads((Path(__file__).resolve().parents[1]/'dist/research.json').read_text())['sources']
 original={s['name']:s['id'] for s in styles}
 for family,raw in DATA.items():
  rows=[line.split('|') for line in raw.strip().splitlines()]; assert len(rows)==10
  idx=next(i for i,f in enumerate(families) if f[0]==family)
  fid,title,kind,old=families[idx]; families[idx]=(fid,title,kind,old+rows)
  for i,(name,signature,topic,uses,resources,motion,nearest,difference,sfx) in enumerate(rows):
   assert nearest in original and name not in original
   slug='-'.join(''.join(c for c in unicodedata.normalize('NFKD',name.lower()) if not unicodedata.combining(c)).split())
   voice,music,_=FAMILY_AUDIO.get(family,('Voz natural e autorizada, coerente com a personagem original.','Trilha discreta com espaço para fala.',''))
   rule=RULE if family=='avatares' else PROPERTY_LOCK if family=='imoveis' else SOFTWARE_LOCK if family=='software' else PRESENTATION_RULE if family=='apresentacoes' else LOCK if family in ['anuncios','campanhas'] else 'Distinguir metáfora de evidência. Não prometer técnica sem executá-la. Sem tremor contínuo; revisar reprodução e escuta.'
   if family=='tecnologia': rule+=' Dados demonstrativos identificados; verificar fonte, unidade, escala, período e incerteza antes de usar dados reais.'
   proof='Demonstrar a ação central descrita, com estado inicial e consequência legíveis, nos 10 segundos; não substituir o mecanismo por zoom em imagem estática. Se faltar captura, rig ou simulação, propor alternativa explícita para aprovação.'
   sources=[r['id'] for r in refs if family in r['families']]
   styles.append(dict(id=slug,name=name,family=family,familyName=title,kind=kind,signature=signature,exampleTopic=topic,uses=uses,resources=resources.split('; '),motion=motion,complexity='Alta / experimental',edition='3.0',novelty=dict(nearestId=original[nearest],nearestName=nearest,difference=difference),proof=proof,researchRefs=sources,note=('Visualização demonstrativa construída em código; dados fictícios, não captura oficial.' if family in ['tecnologia','software'] else 'Estudo estático original gerado por IA. Pessoas, produtos e imóveis fictícios. Não comprova movimento, propriedade física ou desempenho real.'),audio=dict(voice=voice,music=music,sfx=sfx,mix=AUDIO),requirements=rule,image=dict(atlas=f'assets/{family}-bold.webp',column=i%4,row=i//4,columns=4,rows=3,sourceKind='code' if family in ['tecnologia','software'] else 'ai',source='Demonstração em código' if family in ['tecnologia','software'] else 'Estudo visual IA original'),preset=dict(version=4,skill='video-multimarcas',firstDelivery=['roteiro','storyboard visual','vídeo de 10 segundos para aprovação'],avatar=family=='avatares',approvalGate='Aprovar os 10 segundos antes do vídeo completo.',productFidelity=rule,quality=proof)))
